import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaUserCircle, FaHome, FaUpload, FaSignOutAlt, FaVideo, FaUsers, FaCheck, FaTimes, FaBook, FaUserGraduate, FaTrophy, FaTrash, FaQuestionCircle } from 'react-icons/fa';
import { toast } from 'react-toastify';
import { useAuth } from '../../../context/AuthContext';
import enrollmentService from '../../../services/enrollmentService';
import courseService from '../../../services/courseService';
import videoService from '../../../services/videoService';
import Spinner from '../../../components/Spinner';
import '../../../App.css';
import '../../../styles/TeacherDashboard.css';

import UploadContent from './UploadContent';
import AddCourse from './AddCourse';
import StudentRequests from './StudentRequests';
import UploadQuiz from './UploadQuiz';

const TeacherDashboard = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const [isSidebarHovered, setIsSidebarHovered] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [activeCourse, setActiveCourse] = useState(null);

  const [loading, setLoading] = useState(true);
  const [videos, setVideos] = useState([]);
  const [pendingRequests, setPendingRequests] = useState([]);
  const [enrolledStudents, setEnrolledStudents] = useState([]);
  const [courses, setCourses] = useState([]);

  // Fetch teacher data on mount
  useEffect(() => {
    const fetchTeacherData = async () => {
      try {
        setLoading(true);

        // Fetch teacher's courses
        const coursesData = await courseService.getAllCourses();

        // Filter to show only the courses selected by the teacher during registration, 
        // or courses created directly by this teacher.
        const teacherCourses = (coursesData || []).filter(course => {
          const isSelected = Array.isArray(user?.course) 
            ? user.course.includes(course.title) 
            : course.title === user?.course;
          return isSelected || course.teacher_id === user?.id || String(course._id) === String(user?.courseId);
        });

        const registeredCourseTitles = Array.isArray(user?.course) ? user.course : (user?.course ? [user?.course] : []);
        const existingTitles = teacherCourses.map(c => c.title);
        const missingCourseTitles = registeredCourseTitles.filter(title => !existingTitles.includes(title));

        const mockCourses = missingCourseTitles.map((title, index) => ({
          _id: `mock-${title}-${index}`,
          title: title,
          description: "Course selected during registration.",
          isVirtual: true
        }));

        setCourses([...teacherCourses, ...mockCourses]);

        // Fetch enrollment requests and enrolled students for ALL courses
        if (teacherCourses && teacherCourses.length > 0) {
          const firstCourse = teacherCourses[0];
          try {
            let allPendingRequests = [];
            let allEnrolledStudents = [];

            // Loop through all teacher's courses to aggregate data
            for (const course of teacherCourses) {
              const requests = await enrollmentService.getCourseEnrollmentRequests(
                course._id,
                course.yearId || 'default'
              );
              allPendingRequests = [...allPendingRequests, ...requests.filter(r => r.status === 'pending')];

              const enrolled = await enrollmentService.getEnrolledStudents(
                course._id,
                course.yearId || 'default'
              );
              allEnrolledStudents = [...allEnrolledStudents, ...enrolled];
            }

            setPendingRequests(allPendingRequests);
            setEnrolledStudents(allEnrolledStudents);
          } catch (error) {
            console.log('Error fetching enrollment data across courses', error);
          }

          // Fetch videos for the first course (legacy behavior)
          try {
            const videoData = await videoService.getCourseVideos(firstCourse._id);
            setVideos(videoData || []);
          } catch (error) {
            console.log('No videos yet');
          }
        }
      } catch (error) {
        console.error('Error fetching teacher data:', error);
        toast.warning('Some features may be limited. Check your connection.');
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchTeacherData();
    }
  }, [user]);

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  const handleAddCourse = async (e) => {
    e.preventDefault();
    const title = e.target.elements.courseTitle.value;
    const description = e.target.elements.courseDescription.value;

    try {
      const newCourse = await courseService.createCourse({
        title,
        description,
        teacher_id: user.id
      });

      setCourses([...courses, newCourse]);
      toast.success('New course added successfully!');
      e.target.reset();
    } catch (error) {
      console.error('Error creating course:', error);
      toast.error('Failed to create course. Please try again.');
    }
  };

  const handleApprove = async (requestId) => {
    try {
      await enrollmentService.updateEnrollmentStatus(requestId, 'accepted');

      // Update local state
      const approvedRequest = pendingRequests.find(r => r._id === requestId);
      setPendingRequests(pendingRequests.filter(r => r._id !== requestId));

      if (approvedRequest) {
        setEnrolledStudents([...enrolledStudents, approvedRequest]);
      }

      toast.success(`Student has been approved!`);
    } catch (error) {
      console.error('Error approving enrollment:', error);
      toast.error('Failed to approve enrollment. Please try again.');
    }
  };

  const handleReject = async (requestId) => {
    try {
      await enrollmentService.updateEnrollmentStatus(requestId, 'rejected');

      setPendingRequests(pendingRequests.filter(r => r._id !== requestId));
      toast.warning(`Student request has been rejected.`);
    } catch (error) {
      console.error('Error rejecting enrollment:', error);
      toast.error('Failed to reject enrollment. Please try again.');
    }
  };

  const handleUploadSuccess = (newVideo) => {
    setVideos([...videos, newVideo]);
    toast.success('Video uploaded successfully!');
  };

  const handleDeleteVideo = async (videoId) => {
    if (window.confirm('Are you sure you want to delete this video?')) {
      try {
        // API call to delete video would go here
        setVideos(videos.filter(v => v._id !== videoId));
        toast.info('Video deleted successfully');
      } catch (error) {
        console.error('Error deleting video:', error);
        toast.error('Failed to delete video.');
      }
    }
  };

  const handleQuizUploadSuccess = (videoId, quizData) => {
    const updatedVideos = videos.map(v => {
      if (v._id === videoId) {
        return { ...v, quiz: quizData };
      }
      return v;
    });

    setVideos(updatedVideos);
    toast.success('Quiz attached to video successfully!');
    setActiveTab('dashboard');
  };

  if (loading) {
    return <Spinner message="Loading teacher dashboard..." />;
  }

  return (
    <div className="teacher-page-container">
      {/* Top Navigation */}
      <nav className="teacher-top-nav">
        <div className="nav-brand">
          <FaHome size={24} color="#FFFDD0" />
          <span>E-Learn Content</span>
        </div>
        <div className="nav-links">
          <div className={`nav-link ${activeTab === 'dashboard' ? 'active' : ''}`} onClick={() => setActiveTab('dashboard')}>
             Dashboard
          </div>
          <div className={`nav-link ${activeTab === 'my-courses' || activeTab === 'course-dashboard' ? 'active' : ''}`} onClick={() => setActiveTab('my-courses')}>
             Courses
          </div>
          <div className={`nav-link ${activeTab === 'upload' ? 'active' : ''}`} onClick={() => setActiveTab('upload')}>
             Upload Video
          </div>
          <div className={`nav-link ${activeTab === 'quiz' ? 'active' : ''}`} onClick={() => setActiveTab('quiz')}>
             Upload Quiz
          </div>
          <div className={`nav-link ${activeTab === 'requests' ? 'active' : ''}`} onClick={() => setActiveTab('requests')}>
             Requests {pendingRequests.length > 0 && <span className="badge">{pendingRequests.length}</span>}
          </div>
        </div>
        <div className="nav-profile">
          {user?.photo ? (
            <img src={user.photo} alt="Profile" className="profile-img" />
          ) : (
            <FaUserCircle size={35} color="#FFFDD0" />
          )}
          <span>{user?.name || 'Teacher'} &or;</span>
          <FaSignOutAlt size={20} color="#FFFDD0" style={{ cursor: 'pointer', marginLeft: '15px' }} onClick={handleLogout} title="Logout" />
        </div>
      </nav>

      <div className="teacher-main-content">
        <div className="teacher-header-section">
          <h1>Teacher Dashboard</h1>
          <p className="welcome-subtitle">Welcome, {user?.name || 'Teacher'}!</p>
        </div>

        {activeTab === 'dashboard' && (
          <div className="dashboard-grid-layout">
            <div className="dashboard-left-col">
              {/* My Courses */}
              <div className="dashboard-card">
                <div className="card-header">
                  <h2>My Courses</h2>
                </div>
                <div className="my-courses-grid">
                  {courses.map((course, idx) => (
                    <div key={course._id} className="mini-course-card">
                      <div className="course-info">
                        <h3>{course.title}</h3>
                        <p style={{ color: '#008080', fontSize: '0.8rem', fontWeight: 'bold' }}>Active Course</p>
                      </div>
                      <button className="manage-btn" onClick={() => { setActiveCourse(course); setActiveTab('course-dashboard'); }}>Manage</button>
                    </div>
                  ))}
                  {courses.length === 0 && <p style={{ padding: '20px', color: '#666' }}>No courses selected during registration.</p>}
                </div>
              </div>

              {/* Quick Actions */}
              <div className="dashboard-card">
                <div className="card-header">
                  <h2>Quick Actions</h2>
                </div>
                <div className="quick-action-blocks">
                  <div className="action-block orange" onClick={() => setActiveTab('add-course')}>
                    <FaBook size={30} />
                    <span>Add Course</span>
                  </div>
                  <div className="action-block green" onClick={() => setActiveTab('quiz')}>
                    <FaQuestionCircle size={30} />
                    <span>Create Quiz</span>
                  </div>
                  <div className="action-block blue" onClick={() => setActiveTab('upload')}>
                    <FaUpload size={30} />
                    <span>Upload Content</span>
                  </div>
                </div>
                <div className="quick-action-list">
                  <div className="list-item" onClick={() => setActiveTab('add-course')}>
                    <FaBook className="list-icon" /> <span>Add Course</span> <span className="arrow">&rsaquo;</span>
                  </div>
                  <div className="list-item" onClick={() => setActiveTab('quiz')}>
                    <FaQuestionCircle className="list-icon" /> <span>Create Quiz</span> <span className="arrow">&rsaquo;</span>
                  </div>
                  <div className="list-item" onClick={() => setActiveTab('upload')}>
                    <FaUpload className="list-icon" /> <span>Upload Content</span> <span className="arrow">&rsaquo;</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="dashboard-right-col">
              {/* Pending Submissions / Tasks */}
              <div className="dashboard-card">
                <div className="card-header">
                  <h2>Pending Submissions</h2>
                </div>
                <div className="list-container">
                  <div className="list-row"><span>• Assignment 1 (5 Submissions)</span> <button className="review-btn">Review</button></div>
                  <div className="list-row"><span>• Quiz 2 (3 Submissions)</span> <button className="review-btn">Review</button></div>
                  <div className="list-row"><span>• Project Report (2 Submissions)</span> <button className="review-btn">Review</button></div>
                </div>
              </div>

              {/* Enrollment Requests */}
              <div className="dashboard-card">
                <div className="card-header">
                  <h2>Enrollment Requests</h2>
                </div>
                <div className="list-container">
                  {pendingRequests.slice(0, 3).map(req => (
                    <div key={req._id} className="list-row">
                      <span>• {req.student_name} - Pending Approval</span>
                      <div className="action-group">
                        <button className="approve-outline-btn" onClick={() => handleApprove(req._id)}>Approve</button>
                        <button className="reject-outline-btn" onClick={() => handleReject(req._id)}>Reject</button>
                      </div>
                    </div>
                  ))}
                  {pendingRequests.length === 0 && <p className="empty-text">No pending requests.</p>}
                  {pendingRequests.length > 3 && <div className="view-all" onClick={() => setActiveTab('requests')}>View All Requests ({pendingRequests.length})</div>}
                </div>
              </div>

              {/* Class Performance */}
              <div className="dashboard-card">
                <div className="card-header">
                  <h2>Class Performance</h2>
                </div>
                <div className="performance-content">
                  <div className="perf-stats">
                    <p>Average Grade: <strong>82%</strong></p>
                    <p>Tasks Completed: <strong>120</strong></p>
                    <p>Quizzes Taken: <strong>{enrolledStudents.filter(s => s.quizCompleted).length}</strong></p>
                  </div>
                  <div className="chart-mockup">
                    <div className="ring-chart">
                      <span>75%</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* --- Sub Views (Reuse existing logic but in a simple container) --- */}
        {activeTab !== 'dashboard' && (
          <div className="tab-content-container">
            <h2 className="teacher-title sub-title">
              {activeTab === 'my-courses' && "My Courses"}
              {activeTab === 'course-dashboard' && activeCourse && `${activeCourse.title} - Dashboard`}
              {activeTab === 'upload' && 'Upload New Video'}
              {activeTab === 'quiz' && 'Create Video Quiz'}
              {activeTab === 'add-course' && 'Manage Courses'}
              {activeTab === 'requests' && 'Student Approval Panel'}
            </h2>

            {/* Student Requests Section */}
            {activeTab === 'requests' && (
              <StudentRequests requests={pendingRequests} onApprove={handleApprove} onReject={handleReject} />
            )}

            {/* Add Course Section */}
            {activeTab === 'add-course' && (
              <AddCourse onAddCourse={handleAddCourse} />
            )}

            {/* Upload Content Section */}
            {activeTab === 'upload' && (
              <UploadContent onUploadSuccess={handleUploadSuccess} />
            )}

            {/* Upload Quiz Section */}
            {activeTab === 'quiz' && (
              <UploadQuiz videos={videos} onQuizSuccess={handleQuizUploadSuccess} />
            )}

            {/* Course Dashboard Section */}
            {activeTab === 'course-dashboard' && activeCourse && (
              <div className="course-dashboard-section">
                <button 
                  onClick={() => { setActiveTab('my-courses'); setActiveCourse(null); }} 
                  style={{ marginBottom: '20px', padding: '8px 16px', background: '#e0f2f1', color: '#006D5B', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}>
                  &larr; Back to My Courses
                </button>

                <div className="stats-container" style={{ display: 'flex', gap: '20px', marginBottom: '20px' }}>
                  <div className="stat-card" style={{ background: '#f8f9fa', padding: '20px', border: '1px solid #e0e0e0', borderRadius: '10px', flex: 1 }}>
                    <h3 style={{ margin: 0, color: '#333' }}>No. of Enrollments</h3>
                    <p style={{ margin: '10px 0 0 0', fontSize: '1.8rem', fontWeight: 'bold', color: '#fbc02d' }}>
                      {enrolledStudents.filter(s => String(s.course_id) === String(activeCourse._id)).length}
                    </p>
                  </div>
                  <div className="stat-card" style={{ background: '#f8f9fa', padding: '20px', border: '1px solid #e0e0e0', borderRadius: '10px', flex: 1 }}>
                    <h3 style={{ margin: 0, color: '#333' }}>Contents (Videos)</h3>
                    <p style={{ margin: '10px 0 0 0', fontSize: '1.8rem', fontWeight: 'bold', color: '#008080' }}>
                      {videos.length}
                    </p>
                  </div>
                  <div className="stat-card" style={{ background: '#f8f9fa', padding: '20px', border: '1px solid #e0e0e0', borderRadius: '10px', flex: 1 }}>
                    <h3 style={{ margin: 0, color: '#333' }}>Quizzes</h3>
                    <p style={{ margin: '10px 0 0 0', fontSize: '1.8rem', fontWeight: 'bold', color: '#1976d2' }}>
                      0
                    </p>
                  </div>
                </div>

                <div style={{ background: '#f8f9fa', padding: '20px', border: '1px solid #e0e0e0', borderRadius: '10px', marginTop: '20px' }}>
                  <h3 style={{ marginTop: 0 }}>Upload Content for {activeCourse.title}</h3>
                  <UploadContent onUploadSuccess={handleUploadSuccess} />
                </div>
              </div>
            )}

            {/* My Courses Section */}
            {activeTab === 'my-courses' && (
              <div className="my-courses-section">
                <div className="course-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                  {courses.map(course => (
                    <div key={course._id} className="course-card" 
                         style={{ background: '#f8f9fa', border: '1px solid #e0e0e0', padding: '20px', borderRadius: '10px', cursor: 'pointer', borderTop: '4px solid #006D5B' }}
                         onClick={() => {
                            setActiveCourse(course);
                            setActiveTab('course-dashboard');
                         }}>
                      <h3 style={{ margin: '0 0 10px 0', color: '#006D5B' }}>{course.title}</h3>
                      <p style={{ margin: 0, color: '#666', fontSize: '0.9rem' }}>{course.description || "Click to manage enrollments and contents."}</p>
                    </div>
                  ))}
                  {courses.length === 0 && <p>No courses found. Selected courses will appear here.</p>}
                </div>
              </div>
            )}

          </div>
        )}
      </div>
    </div>
  );
};

export default TeacherDashboard;
